def draw_text(page: fitz.Page, x: float, y: float, text: str, fontsize: float = 10) -> float:
    text = latexish_to_text(text)
    if not text:
        return y
    width = PAGE_W - MARGIN - x
    # Approximate wrap
    words = text.replace("\n", " \n ").split()
    lines: list[str] = []
    cur = ""
    for word in words:
        if word == "\n":
            lines.append(cur)
            cur = ""
            continue
        trial = (cur + " " + word).strip()
        if fitz.get_text_length(trial, fontname=FONT, fontsize=fontsize) <= width:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    for line in lines:
        page.insert_text((x, y + fontsize), line, fontsize=fontsize, fontname=FONT)
        y += fontsize + 3
    return y + 4


