    for _ in range(20):
        if y1 - y0 < 40:
            break
        strip = ink[max(y0, y1 - 16) : y1 + 1, :]
        if strip.size == 0:
            break
        xs = np.where(strip.any(axis=0))[0]
        if not xs.size:
            y1 -= 8
            continue
        row_proxy = strip.any(axis=0)
        span = int(xs[-1] - xs[0])
        if (
            _row_is_paragraph_text(row_proxy, w, x0, x1)
            or (span > w * 0.55 and float(strip.mean()) > 0.028)
            or (wide_fig and span > w * 0.5 and float(strip.mean()) > 0.02)
        ):
            y1 = max(y0 + 30, y1 - 10)
        else:
            break

    return CropBox(x0, y0, x1, y1)

