def remove_stem_figure(conn, question_id: str) -> None:
    """Drop a false-positive stem figure and keep text-only stem blocks."""
    texts = _existing_stem_text(conn, question_id)
    stem_assets = [
        r[0]
        for r in conn.execute(
            """
            SELECT asset_id FROM asset_role
            WHERE question_id = ? AND role = 'stem_figure'
            """,
            (question_id,),
        )
    ]
    conn.execute(
        "DELETE FROM asset_role WHERE question_id = ? AND role = 'stem_figure'",
        (question_id,),
    )
    # Clear figure content_blocks; rebuild text blocks if needed
    conn.execute(
        """
        DELETE FROM content_block
        WHERE question_id = ? AND block_type = 'figure'
        """,
        (question_id,),
    )
    remaining = conn.execute(
        """
        SELECT COUNT(*) FROM content_block
        WHERE question_id = ? AND block_type = 'text'
        """,
        (question_id,),
    ).fetchone()[0]
    if remaining == 0 and texts:
        for i, chunk in enumerate(texts):
            conn.execute(
                """
                INSERT INTO content_block (id, question_id, position, block_type, text_content)
                VALUES (?, ?, ?, 'text', ?)
                """,
                (f"{question_id}:cb{i}", question_id, i, chunk),
            )
    elif remaining > 0:
        # Compact positions after deleting figures
        rows = conn.execute(
            """
            SELECT id FROM content_block
            WHERE question_id = ? AND block_type = 'text'
            ORDER BY position
            """,
            (question_id,),
        ).fetchall()
        for i, (cid,) in enumerate(rows):
            conn.execute(
                "UPDATE content_block SET position = ?, asset_id = NULL, figure_label = NULL WHERE id = ?",
                (i, cid),
            )
    for asset_id in stem_assets:
        still = conn.execute(
            "SELECT 1 FROM asset_role WHERE asset_id = ? LIMIT 1",
            (asset_id,),
        ).fetchone()
        used = conn.execute(
            "SELECT 1 FROM content_block WHERE asset_id = ? LIMIT 1",
            (asset_id,),
        ).fetchone()
        if not still and not used:
            conn.execute("DELETE FROM asset WHERE id = ?", (asset_id,))
    conn.commit()
    print(f"  removed stem figure {question_id}", flush=True)


