def _row_figure_signal(ink_row: np.ndarray, page_w: int) -> tuple[str, int]:
    """Classify a scanline: empty | prose | figure. Returns (kind, ink_count)."""
    xs = np.where(ink_row)[0]
    n = int(xs.size)
    if n < 4:
        return "empty", n
    span = int(xs[-1] - xs[0]) + 1
    density = n / max(1, span)
    # Full-width dense lines are stem/option prose, not diagram ink
    if span > page_w * 0.55 and n > 28 and density > 0.12:
        return "prose", n
    if span > page_w * 0.72 and n > 40:
        return "prose", n
    return "figure", n


def _figure_bands(
    gray: np.ndarray, top: int, bottom: int
) -> list[tuple[int, int, float]]:
    """Return (y0, y1, score) bands of contiguous non-prose figure ink."""
    h, w = gray.shape
    ink = gray < 175
    bands: list[tuple[int, int, float]] = []
    y = top
    while y < bottom:
        kind, _n = _row_figure_signal(ink[y], w)
        if kind != "figure":
            y += 1
            continue
        y0 = y
        score = 0.0
        empty_run = 0
        while y < bottom:
            kind, n = _row_figure_signal(ink[y], w)
            if kind == "prose":
                break
            if kind == "empty":
                empty_run += 1
                # Allow small gaps inside sparse diagrams (dashed lines, labels)
                if empty_run > 18:
                    break
            else:
                empty_run = 0
                score += float(n) + 8.0
            y += 1
        y1 = y - empty_run - 1
        if y1 - y0 >= 28 and score > 400:
            bands.append((y0, y1, score))
        # Skip past the gap/prose we stopped on
        while y < bottom and _row_figure_signal(ink[y], w)[0] != "figure":
            y += 1
    return bands


def _bbox_in_band(gray: np.ndarray, y0: int, y1: int) -> CropBox | None:
    """Tight ink bbox inside a figure band, ignoring left margin question numbers."""
    h, w = gray.shape
    ink = gray < 175
    # Ignore far-left question number / asterisk column
    x_left = max(40, int(w * 0.04))
    region = ink[y0 : y1 + 1, x_left:]
    ys, xs = np.where(region)
    if xs.size < 40:
        return None
    return CropBox(
        x_left + int(xs.min()),
        y0 + int(ys.min()),
        x_left + int(xs.max()),
        y0 + int(ys.max()),
    )


def find_stem_figure_box(gray: np.ndarray, option_y0: int | None = None) -> CropBox | None:
    """Find a stem diagram above the options.

    Prefer a vertical *figure zone* (union of sparse diagram ink) over picking a
    single connected component. Component clustering alone often keeps only the
    densest fragment (axes, ground hatching, one force arrow).
    """
    h, w = gray.shape
    if option_y0 is None:
        option_y0 = find_option_band_y0(gray)
    top = int(h * 0.02)
    bottom = (option_y0 - 4) if option_y0 is not None else int(h * 0.72)
    bottom = max(top + 30, min(h - 2, bottom))
    if bottom - top < 36:
        return None

    bands = _figure_bands(gray, top, bottom)
    best_box: CropBox | None = None
    best_score = -1.0
    for y0, y1, band_score in bands:
        box = _bbox_in_band(gray, y0, y1)
        if box is None:
